import org.junit.Test;
import org.jsoup.parser.Tag;
import org.jsoup.parser.ParseSettings;

import static org.junit.Assert.*;

public class TagTest {
    @Test
    public void getNameTest() {
        Tag tag = Tag.valueOf("a");
        assertEquals("a", tag.getName());
    }

    @Test
    public void normalNameTest() {
        Tag tag = Tag.valueOf("A");
        assertEquals("a", tag.normalName());
    }

    @Test
    public void valueOfStringTest() {
        Tag tag = Tag.valueOf("p");
        assertNotNull(tag);
        assertEquals("p", tag.getName());
    }

    @Test
    public void valueOfStringAndParseSettingsTest() {
        Tag tag = Tag.valueOf("P", ParseSettings.htmlDefault);
        assertNotNull(tag);
        assertEquals("p", tag.getName());
    }

    @Test
    public void isBlockTest() {
        Tag tag = Tag.valueOf("div");
        assertTrue(tag.isBlock());
    }

    @Test
    public void isInlineTest() {
        Tag tag = Tag.valueOf("span");
        assertTrue(tag.isInline());
    }

    @Test
    public void isEmptyTest() {
        Tag tag = Tag.valueOf("img");
        assertTrue(tag.isEmpty());
    }

    @Test
    public void isSelfClosingTest() {
        Tag tag = Tag.valueOf("br");
        assertTrue(tag.isSelfClosing());
    }

    @Test
    public void isKnownTagTest() {
        Tag tag = Tag.valueOf("div");
        assertTrue(tag.isKnownTag());
    }

    @Test
    public void isKnownTagStringTest() {
        assertTrue(Tag.isKnownTag("span"));
    }

    @Test
    public void preserveWhitespaceTest() {
        Tag tag = Tag.valueOf("pre");
        assertTrue(tag.preserveWhitespace());
    }

    @Test
    public void isFormListedTest() {
        Tag tag = Tag.valueOf("form");
        assertTrue(tag.isFormListed());
    }

    @Test
    public void isFormSubmittableTest() {
        Tag tag = Tag.valueOf("button");
        assertTrue(tag.isFormSubmittable());
    }

    @Test
    public void setSelfClosingTest() {
        Tag tag = Tag.valueOf("span");
        tag = tag.setSelfClosing();
        assertTrue(tag.isSelfClosing());
    }

    @Test
    public void equalsTest() {
        Tag tag1 = Tag.valueOf("a");
        Tag tag2 = Tag.valueOf("a");
        assertTrue(tag1.equals(tag2));
    }

    @Test
    public void hashCodeTest() {
        Tag tag = Tag.valueOf("div");
        assertNotNull(tag.hashCode());
    }

    @Test
    public void toStringTest() {
        Tag tag = Tag.valueOf("p");
        assertEquals("<p>", tag.toString());
    }

    @Test
    public void cloneTest() {
        Tag tag1 = Tag.valueOf("a");
        Tag tag2 = tag1.clone();
        assertEquals(tag1, tag2);
    }
}
